pub fn insert(&mut self, range: Range<u32>) {
    if range.start >= range.end {
        return;
    }
    let mut start = range.start;
    let mut end = range.end;
    // A stored range that reaches `start` (overlapping or adjacent) joins the new one.
    if let Some((&s, &e)) = self.ranges.range(..=start).next_back() {
        if e >= start {
            self.ranges.remove(&s);
            start = s;
            end = end.max(e);
        }
    }
    // Every stored range that begins within, or touches, the new one joins it.
    while let Some((&s, &e)) = self.ranges.range(start..=end).next() {
        self.ranges.remove(&s);
        end = end.max(e);
    }
    self.ranges.insert(start, end);
}

