pub fn remove(&mut self, range: Range<u32>) {
    if range.start >= range.end {
        return;
    }
    let (start, end) = (range.start, range.end);
    // A stored range that starts before `start` keeps its head; if it also
    // runs past `end` it keeps its tail too, and nothing else overlaps.
    if let Some((&s, &e)) = self.ranges.range(..start).next_back() {
        if e > start {
            self.ranges.insert(s, start);
            if e > end {
                self.ranges.insert(end, e);
                return;
            }
        }
    }
    // Stored ranges starting inside `[start, end)` are removed; only the last
    // of them can extend past `end`, and its tail is kept.
    while let Some((&s, &e)) = self.ranges.range(start..end).next() {
        self.ranges.remove(&s);
        if e > end {
            self.ranges.insert(end, e);
            break;
        }
    }
}

