use fixture::IntervalSet;

fn ranges(set: &IntervalSet) -> Vec<std::ops::Range<u32>> {
    set.iter().collect()
}

#[test]
fn adjacent_inserts_merge() {
    let mut set = IntervalSet::new();
    set.insert(1..3);
    set.insert(3..5);
    assert_eq!(ranges(&set), vec![1..5]);
}

#[test]
fn insert_bridges_several_ranges() {
    let mut set = IntervalSet::new();
    set.insert(0..2);
    set.insert(4..6);
    set.insert(8..10);
    set.insert(2..8);
    assert_eq!(ranges(&set), vec![0..10]);
    assert_eq!(set.len(), 10);
}

#[test]
fn empty_ranges_change_nothing() {
    let mut set = IntervalSet::new();
    set.insert(5..5);
    set.insert(7..3);
    assert!(set.is_empty());
    set.insert(1..4);
    set.insert(2..2);
    set.remove(3..3);
    set.remove(9..1);
    assert_eq!(ranges(&set), vec![1..4]);
}

#[test]
fn remove_from_middle_splits() {
    let mut set = IntervalSet::new();
    set.insert(0..10);
    set.remove(3..6);
    assert_eq!(ranges(&set), vec![0..3, 6..10]);
    assert_eq!(set.len(), 7);
    assert!(set.contains(2));
    assert!(!set.contains(3));
    assert!(!set.contains(5));
    assert!(set.contains(6));
}

#[test]
fn remove_spanning_several_ranges() {
    let mut set = IntervalSet::new();
    set.insert(0..2);
    set.insert(4..6);
    set.insert(8..10);
    set.remove(1..9);
    assert_eq!(ranges(&set), vec![0..1, 9..10]);
}

#[test]
fn remove_absent_points_is_a_no_op() {
    let mut set = IntervalSet::new();
    set.insert(0..2);
    set.insert(5..7);
    set.remove(2..5);
    set.remove(10..20);
    assert_eq!(ranges(&set), vec![0..2, 5..7]);
}

#[test]
fn removing_everything_empties_the_set() {
    let mut set = IntervalSet::new();
    set.insert(3..9);
    set.remove(0..100);
    assert!(set.is_empty());
    assert_eq!(set.len(), 0);
}

#[test]
fn reaches_u32_max() {
    let mut set = IntervalSet::new();
    set.insert(0..u32::MAX);
    assert_eq!(set.len(), u64::from(u32::MAX));
    assert!(set.contains(u32::MAX - 1));
    assert!(!set.contains(u32::MAX));
    assert_eq!(ranges(&set), vec![0..u32::MAX]);
}

#[test]
fn max_end_merges_and_splits_without_overflow() {
    let mut set = IntervalSet::new();
    set.insert(u32::MAX - 10..u32::MAX);
    set.insert(u32::MAX - 20..u32::MAX - 10);
    assert_eq!(ranges(&set), vec![u32::MAX - 20..u32::MAX]);
    set.remove(u32::MAX - 15..u32::MAX - 5);
    assert_eq!(
        ranges(&set),
        vec![u32::MAX - 20..u32::MAX - 15, u32::MAX - 5..u32::MAX]
    );
    assert_eq!(set.len(), 20);
    assert!(!set.contains(u32::MAX));
}

#[test]
fn point_u32_max_is_never_contained() {
    let mut set = IntervalSet::new();
    set.insert(u32::MAX - 1..u32::MAX);
    assert!(set.contains(u32::MAX - 1));
    assert!(!set.contains(u32::MAX));
    set.remove(u32::MAX - 1..u32::MAX);
    assert!(set.is_empty());
}

#[test]
fn same_points_give_same_ranges() {
    let mut a = IntervalSet::new();
    a.insert(0..4);
    a.insert(4..8);
    let mut b = IntervalSet::new();
    b.insert(4..8);
    b.insert(0..4);
    assert_eq!(a, b);
    assert_eq!(ranges(&a), vec![0..8]);
}

/// Checks every operation against a plain bitmap over a small domain.
#[test]
fn matches_bitmap_model() {
    const DOMAIN: u32 = 64;
    let mut state: u64 = 0x2545_f491_4f6c_dd1d;
    let mut next = move |bound: u32| {
        state = state
            .wrapping_mul(6_364_136_223_846_793_005)
            .wrapping_add(1_442_695_040_888_963_407);
        ((state >> 33) % u64::from(bound)) as u32
    };

    for _round in 0..200 {
        let mut set = IntervalSet::new();
        let mut model = [false; DOMAIN as usize];
        for _op in 0..40 {
            let start = next(DOMAIN + 4);
            let end = start + next(12);
            let range = start..end.min(DOMAIN + 4);
            if next(2) == 0 {
                set.insert(range.clone());
                for p in range {
                    if (p as usize) < model.len() {
                        model[p as usize] = true;
                    }
                }
            } else {
                set.remove(range.clone());
                for p in range {
                    if (p as usize) < model.len() {
                        model[p as usize] = false;
                    }
                }
            }

            let mut expected = Vec::new();
            let mut p = 0;
            while p < DOMAIN {
                if model[p as usize] {
                    let s = p;
                    while p < DOMAIN && model[p as usize] {
                        p += 1;
                    }
                    expected.push(s..p);
                } else {
                    p += 1;
                }
            }
            assert_eq!(ranges(&set), expected);
            assert_eq!(set.len(), model.iter().filter(|&&b| b).count() as u64);
            assert_eq!(set.is_empty(), expected.is_empty());
            for p in 0..DOMAIN + 4 {
                assert_eq!(set.contains(p), p < DOMAIN && model[p as usize], "point {p}");
            }
        }
    }
}

